selected.compute:
options = read('/input/options')
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for combo in combinations(options, size):
        ids = [item['id'] for item in combo]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
